'use strict';

// Generated by scripts/stage-vendors.js. Runs inside the sandboxed PDF iframe.
(() => {
  const VERSION = 1;
  const MAX_BYTES = 20 * 1024 * 1024;
  const SET_WATERMARK = 'kusunoki:pdf:set-watermark';
  const PING = 'kusunoki:pdf:ping';
  const READY = 'kusunoki:pdf:ready';
  const APPLIED = 'kusunoki:pdf:watermark-applied';
  const ERROR = 'kusunoki:pdf:error';
  const MIME_TYPES = new Set(['image/png', 'image/jpeg', 'image/jpg', 'image/svg+xml']);

  const isRecord = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
  const bytesFrom = (value) => {
    if (value instanceof ArrayBuffer) return value.slice(0);
    if (ArrayBuffer.isView(value)) return value.buffer.slice(value.byteOffset, value.byteOffset + value.byteLength);
    return null;
  };
  const originAllowed = (event) => {
    if (!event || event.source !== window.parent) return false;
    const origin = String(event.origin || '');
    const ownOrigin = String(window.location?.origin || 'null');
    return origin === 'null' || origin === ownOrigin;
  };
  const safeFileName = (value) => {
    const fileName = String(value || 'qr-watermark.png');
    if (!fileName || fileName.length > 160 || fileName === '.' || fileName === '..' || /[\u0000-\u001f<>:"/\\|?*]/u.test(fileName)) return null;
    return fileName;
  };
  const post = (type, payload) => {
    window.parent.postMessage({ version: VERSION, type, payload }, '*');
  };
  const validate = (event) => {
    if (!originAllowed(event)) return null;
    const message = event.data;
    if (!isRecord(message) || message.version !== VERSION || typeof message.type !== 'string') return null;
    if (message.type === PING) return { type: PING, payload: {} };
    if (message.type !== SET_WATERMARK || !isRecord(message.payload)) return null;
    const raw = bytesFrom(message.payload.data);
    const fileName = safeFileName(message.payload.fileName);
    const mimeType = String(message.payload.mimeType || 'image/png');
    const text = String(message.payload.text || '');
    if (!raw || raw.byteLength < 1 || raw.byteLength > MAX_BYTES || !fileName || !MIME_TYPES.has(mimeType) || text.length > 4096) return null;
    return { type: SET_WATERMARK, payload: { data: raw, fileName, mimeType, text } };
  };
  const applyWatermark = (payload) => {
    const input = document.getElementById('wm-img-input');
    const mode = document.getElementById('mode-watermark');
    if (!input || !mode || typeof File !== 'function' || typeof DataTransfer !== 'function') throw new Error('PDFウォーターマーク入力欄を利用できません。');
    const file = new File([payload.data], payload.fileName, { type: payload.mimeType });
    const transfer = new DataTransfer();
    transfer.items.add(file);
    input.files = transfer.files;
    if (!mode.checked) {
      mode.checked = true;
      mode.dispatchEvent(new Event('change', { bubbles: true }));
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    post(APPLIED, { fileName: payload.fileName, mimeType: payload.mimeType, byteLength: payload.data.byteLength });
  };
  window.addEventListener('message', (event) => {
    if (!originAllowed(event)) return;
    const checked = validate(event);
    if (!checked) {
      if (event.data && event.data.type === SET_WATERMARK) post(ERROR, { code: 'invalid-message', message: 'PDF受渡しメッセージが不正です。' });
      return;
    }
    if (checked.type === PING) {
      post(READY, { source: 'generated/upstream/pdf', version: VERSION, capabilities: ['watermark-file'] });
      return;
    }
    try {
      applyWatermark(checked.payload);
    } catch (error) {
      post(ERROR, { code: 'apply-failed', message: error instanceof Error ? error.message : String(error) });
    }
  });
  window.addEventListener('DOMContentLoaded', () => {
    post(READY, { source: 'generated/upstream/pdf', version: VERSION, capabilities: ['watermark-file'] });
  });
})();
